{"tool":"write","path":"tests/test_export_extra.py","content":""""Optional supplementary tests for reports.export.export_csv."""
import unittest

from reports import export_csv


class ExportCsvExtraTests(unittest.TestCase):
    def test_generators(self):
        rows = ({"a": i, "b": i * 2} for i in range(3))
        cols = (c for c in ["a", "b"])
        self.assertEqual(export_csv(rows, cols), "a,b\r\n0,0\r\n1,2\r\n2,4\r\n")

    def test_empty_columns(self):
        self.assertEqual(export_csv([{"a": 1}], []), "\r\n")
        self.assertEqual(export_csv([], []), "\r\n")

    def test_none_and_missing(self):
        self.assertEqual(
            export_csv([{"a": None, "b": 2}], ["a", "b", "c"]),
            "a,b,c\r\n,2,\r\n",
        )

    def test_str_values(self):
        self.assertEqual(
            export_csv([{"a": 1.5, "b": True}], ["a", "b"]),
            "a,b\r\n1.5,True\r\n",
        )

    def test_embedded_newlines_and_unicode(self):
        self.assertEqual(
            export_csv([{"a": "x\ny\rz\r\n", "b": "caf\u00e9 \u2603"}], ["a", "b"]),
            'a,b\r\n"x\ny\rz\r\n",caf\u00e9 \u2603\r\n',
        )

    def test_quote_doubling_minimal(self):
        self.assertEqual(
            export_csv([{"a": 'say "hi"'}], ["a"]),
            'a\r\n"say ""hi"""\r\n',
        )
        # plain text with no special chars is not quoted
        self.assertEqual(export_csv([{"a": "plain"}], ["a"]), "a\r\nplain\r\n")

    def test_duplicate_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([{"a": 1}], ["a", "a"])

    def test_non_string_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([{"1": 1}], [1])
        with self.assertRaises(ValueError):
            export_csv([], [None])

    def test_unselected_fields_ignored_and_inputs_not_mutated(self):
        row = {"b": 2, "a": 1, "extra": "x"}
        cols = ["a", "b"]
        self.assertEqual(export_csv([row], cols), "a,b\r\n1,2\r\n")
        self.assertEqual(row, {"b": 2, "a": 1, "extra": "x"})
        self.assertEqual(cols, ["a", "b"])


if __name__ == "__main__":
    unittest.main()
